#include <iostream>

int main() {
    int total = 0;
    for (int i = 1; i <= 3; ++i) {
        total += i;
    }
    std::cout << total << "\n";
    int count = 2;
    while (count > 0) {
        std::cout << count << "\n";
        --count;
    }
    return 0;
}

